from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_22R4 import ResetRf22R4


class ResetRf23R1(ResetRf22R4):
    def get_kpi(self):
        """
        Gets kpi for reset rf operation.
        :return: dictionary with timeout, requirement and operation description for reset rf
        :rtype: dict
        """

        if all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 3,
                    not self.bts.is_multi_rat,
                    self.bts.number_of_rmods <= 4,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "SA",
                    self.bts.radio_protocol == "CPRI",
                    "AHEGB" in self.bts.rmod_hw_types,
                    "AHEH" in self.bts.rmod_hw_types or "AHLOA" in self.bts.rmod_hw_types
                ]
        ):
            self.operation_details[
                "Timeout"] += 288 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_12847()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17292"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.is_multi_rat,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_lte_cells <= 3,
                    self.bts.cell_technologies == "FDD",
                    self.bts.radio_protocol == "CPRI",
                ]
        ):
            self.operation_details[
                "Timeout"] += 240 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_12847()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19822"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 4,
                    not self.bts.is_multi_rat,
                    self.bts.cell_technologies == "MIX",
                    self.bts.setup_mode == "NSA",
                ]
        ):
            self.operation_details[
                "Timeout"] += 240 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_12847()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19836"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIO", "ABIN"]),
                    self.bts.number_of_bbmods <= 3,
                    self.bts.setup_mode == "SA",
                ]
        ):
            self.operation_details[
                "Timeout"] += 288 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_12847()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19205"

        else:
            return super(ResetRf23R1, self).get_kpi()

        return self.operation_details
